@Composable fun SalaryAllocationDetailRoute(args:SalaryAllocationDetailArgs,onBack:()->Unit,onEditCategory:(Long)->Unit,stateHolder:SalaryAllocationDetailStateHolder=koinInject(parameters={parametersOf(args)})) { val state by stateHolder.state.collectAsStateWithLifecycle();DisposableEffect(stateHolder){stateHolder.start();onDispose{stateHolder.close()}};SalaryAllocationDetailScreen(state,stateHolder::onAction,onBack,onEditCategory) }

