@Composable private fun DetailHero(state: SalaryAllocationDetailUiState){val category=state.category?:return;val target=state.targetAmountWon;val total=state.childTotalWon;val diff=if(target!=null&&total!=null)target-total else null;Surface(color=Color.White,shape=RoundedCornerShape(16.dp),border=BorderStroke(1.dp,MoaLogColors.CardBorder)){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Row(verticalAlignment=Alignment.CenterVertically){Surface(shape=CircleShape,color=Color(0xFFE7F0ED)){Icon(Icons.Default.TrendingUp,null,Modifier.padding(10.dp),tint=MoaLogColors.DeepTeal)};Column(Modifier.padding(start=10.dp)){Text(category.name,fontWeight=FontWeight.Bold);Text("${category.attributionMonth.year}년 ${category.attributionMonth.month}월 배분",color=MoaLogColors.MutedInk,style=MaterialTheme.typography.labelSmall)}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(12.dp)){HeroMetric("목표 배분액",target?.let(::detailWon)?:"계산 불가",Modifier.weight(1f));HeroMetric("세부 합계",if(state.hasChildTotalOverflow)"합계 범위 초과" else total?.let(::detailWon)?:"미입력",Modifier.weight(1f))};LinearProgressIndicator(progress={if(target!=null&&target>0&&total!=null)(total.toDouble()/target.toDouble()).toFloat().coerceIn(0f,1f) else 0f},Modifier.fillMaxWidth().semantics{contentDescription="목표 배분액과 세부 합계 진행률"},color=MoaLogColors.DeepTeal,trackColor=Color(0xFFE0E3DF));if(diff!=null&&diff!=0L)Row(Modifier.fillMaxWidth().background(Color(0xFFFDECEE),RoundedCornerShape(10.dp)).padding(10.dp)){Icon(Icons.Default.Warning,null,tint=MoaLogColors.Overspend);Text("차액 ${detailWon(kotlin.math.abs(diff))} ${if(diff>0)"미배분" else "초과"}",Modifier.padding(start=8.dp),color=MoaLogColors.Overspend,fontWeight=FontWeight.SemiBold)}}}}
@Composable private fun HeroMetric(label:String,value:String,modifier:Modifier=Modifier){Column(modifier){Text(label,color=MoaLogColors.MutedInk,style=MaterialTheme.typography.labelSmall);Text(value,style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold,color=MoaLogColors.TealInk)}}
