@Composable private fun DetailField(label:String,value:String,onChange:(String)->Unit,placeholder:String){Column(verticalArrangement=Arrangement.spacedBy(6.dp)){Text(label,style=MaterialTheme.typography.labelMedium,fontWeight=FontWeight.SemiBold);OutlinedTextField(value,onChange,Modifier.fillMaxWidth().heightIn(min=52.dp),placeholder={Text(placeholder)},singleLine=true,shape=RoundedCornerShape(10.dp))}}
private fun detailWon(value:Long)=value.toString().reversed().chunked(3).joinToString(",").reversed()+"원"
private fun addWonInput(value: String, increment: Long): String {
    val current = value.toLongOrNull() ?: 0L
    return if (Long.MAX_VALUE - current < increment) value else (current + increment).toString()
}
